type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const clone = (v: any): any => JSON.parse(JSON.stringify(v));
  const original = clone(d.value),
    updated = clone(d.value);
  let n = updated;
  for (const k of d.path.slice(0, -1)) n = n[k];
  n[d.path.at(-1)] = clone(d.replacement);
  return { updated, original };
}
